-- Picture-in-Picture
hl.window_rule({
    match = {
        title = "^(Picture(-| )in(-| )[Pp]icture)$",
    },
    keep_aspect_ratio = true,
    move = "73% 72%",
    size = "25% 25%",
    float = true,
    pin = true,
    opacity = "1.0 override",
})

-- Plex Media Player
hl.window_rule({
    match = {
        title = "^(tv.plex.Plex|Plex)$",
    },
    keep_aspect_ratio = true,
    move = "73% 72%",
    size = "45% 45%",
    float = true,
    pin = true,
    opacity = "1.0 override",
})

