    match = {
        float = 0,
    },
    no_shadow = true,
})

-- ######## Layer rules ########
hl.layer_rule({
    match = { namespace = ".*" },
    xray = true,
})

-- layerrule = animation none, match:namespace .*
hl.layer_rule({
    match = { namespace = "walker" },
    animation = "none",
})

hl.layer_rule({
    match = { namespace = "selection" },
    animation = "none",
})

hl.layer_rule({
    match = { namespace = "overview" },
    animation = "none",
})

hl.layer_rule({
    match = { namespace = "anyrun" },
    animation = "none",
})

hl.layer_rule({
    match = { namespace = "indicator.*" },
    animation = "none",
})

hl.layer_rule({
    match = { namespace = "osk" },
    animation = "none",
})

hl.layer_rule({
    match = { namespace = "hyprpicker" },
    animation = "none",
})

hl.layer_rule({
    match = { namespace = "shell:*" },
    blur = true,
    ignore_alpha = 0.6,
})

hl.layer_rule({
    match = { namespace = "noanim" },
    animation = "none",
})

hl.layer_rule({
    match = { namespace = "gtk-layer-shell" },
    blur = true,
    ignore_alpha = 0,
})

hl.layer_rule({
    match = { namespace = "launcher" },
    blur = true,
    ignore_alpha = 0.5,
})

hl.layer_rule({
    match = { namespace = "notifications" },
    blur = true,
    ignore_alpha = 0.69,
})

